questionvariables.text:
plist: [[0,"VBC",7.1,7.9,"h",2.6,"VMO",["OVM","VCO","VMC","VMO"]],[1,"VAB",23,12,"h",9,"VNO",["VNA","VNO","VAO","OVN"]],[2,"VBC",4.9,5.4,"h",2.5,"VMO",["OVM","VCO","VMC","VMO"]],[3,"VAB",14,9,"e",20,"VNO",["VAO","VNO","OVN","VNA"]],[0,"VBC",8.5,7.3,"h",3.2,"VMO",["OVM","VMO","VMC","VCO"]],[1,"VAB",23,11,"h",24,"VNO",["VAO","VNO","VNA","OVN"]],[2,"VBC",4.8,3,"h",2.8,"VMO",["VCO","VMC","OVM","VMO"]],[3,"VAB",19,8,"e",23,"VNO",["VAO","VNA","OVN","VNO"]],[0,"VBC",8.4,6.1,"e",6.3,"VMO",["OVM","VMO","VCO","VMC"]],[1,"VAB",21,20,"h",11,"VNO",["VAO","VNA","OVN","VNO"]]];
/* Design: angle between a face and the base of a pyramid. Faces alternate VBC (angle VMO, OM = AB/2) and VAB (angle VNO, ON = BC/2); three entries give the sloping edge. Source: adapted from SMP Book 5 (Metric), Chapter 7, section 2(a) and Exercise D, Q5(c). */
CT: [["The roof of a gazebo","m"],["A model pyramid","cm"],["A pyramid tent","m"],["A glass paperweight","cm"]];
ix: 1+rand(10); PP: plist[ix];
ctx: CT[PP[1]+1][1]; un: CT[PP[1]+1][2]; face: PP[2]; ll: PP[3]; ww: PP[4]; isH: is(PP[5] = "h"); gv: PP[6]; nm: PP[7]; OP: PP[8];
hh: if isH then gv else sqrt(gv^2 - (ll^2+ww^2)/4);
LS: "ABCDVOMN"; LT: [[0,0,0],[ll,0,0],[ll,ww,0],[0,ww,0],[ll/2,ww/2,hh],[ll/2,ww/2,0],[ll,ww/2,0],[ll/2,0,0]];
pt(c) := LT[ssearch(c, LS)];
vv(s) := pt(charat(s,2)) - pt(charat(s,1));
sq(s) := vv(s) . vv(s);
dst(s) := float(sqrt(sq(s)));
angd(s) := block([u,w], u: pt(charat(s,1))-pt(charat(s,2)), w: pt(charat(s,3))-pt(charat(s,2)), float(acos((u . w)/sqrt((u . u)*(w . w)))*180/%pi));
r1(v) := float(floor(10*v+1/2)/10); r2(v) := float(floor(100*v+1/2)/100);
d1(v) := dispdp(r1(v),1); d2(v) := dispdp(r2(v),2); d4(v) := dispdp(float(floor(10000*v+1/2)/10000),4);
NA: -999; NB: -888; NC: -777;
nf(v) := if integerp(v) then v else float(v);
r4(v) := float(floor(10000*v+1/2)/10000);
isM: is(face = "VBC"); mid: if isM then "M" else "N"; cl: if isM then "BC" else "AB"; parl: if isM then "AB" else "BC";
cor: if isM then "C" else "A";
near: nf(if isM then ll/2 else ww/2); far: if isM then ww/2 else ll/2;
SH: r4(hh^2); SA: r4(sq("OA"));
th: angd(nm); oh: float(atan(hh/far)*180/%pi); edg: angd("VAO"); cp: 90-th;
thr: r1(th); tha: th+0.2; thg: th+1.0; thrad: float(th*%pi/180);
opts: makelist([o, is(o = nm), o], o, OP);
oV: first(sublist(OP, lambda([o], is(charat(o,2) = "V"))));
oE: first(sublist(OP, lambda([o], is(charat(o,3) = "O" and charat(o,2) # mid))));
oI: first(sublist(OP, lambda([o], is(charat(o,3) # "O"))));
